#include <pthread.h>
#include <stdio.h>
#include <sys/syscall.h>
#include <unistd.h>

static int counter = 0;

static void *work(void *arg) {
    (void)arg;
    counter += 100;
    printf("thread: pid=%d tid=%ld counter=%d at %p\n",
           getpid(), syscall(SYS_gettid), counter, (void *)&counter);
    return NULL;
}

int main(void) {
    printf("main:   pid=%d tid=%ld counter=%d at %p\n",
           getpid(), syscall(SYS_gettid), counter, (void *)&counter);
    pthread_t t;
    pthread_create(&t, NULL, work, NULL);
    pthread_join(t, NULL);
    printf("main:   counter=%d after the thread ended\n", counter);
    return 0;
}

#include <stdio.h>
#include <time.h>

int main(void) {
    struct timespec t0, t;
    volatile unsigned long n = 0;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    do {
        for (int i = 0; i < 100000; i++)
            n++;
        clock_gettime(CLOCK_MONOTONIC, &t);
    } while (t.tv_sec - t0.tv_sec < 3);        /* burn CPU for 3 seconds */
    printf("%lu million loops\n", n / 1000000);
    return 0;
}

